    scripture: ["Deuteronomy 30:11-20", "Deuteronomy 28:1-2"], more: ["Deuteronomy 6:4-9", "Deuteronomy 30:1-6", "Joshua 24:14-15"], memory: "Deuteronomy 30:19",
